function cheapestRoute(n: number, roads: number[][]): number {
  const dist = new Array(n).fill(Infinity);
  dist[0] = 0;
  for (let round = 0; round < n - 1; round++) {
    let changed = false;
    for (const [u, v, w] of roads) {
      if (dist[u] + w < dist[v]) { dist[v] = dist[u] + w; changed = true; }
      if (dist[v] + 2 * w < dist[u]) { dist[u] = dist[v] + 2 * w; changed = true; }
    }
    if (!changed) break;
  }
  return dist[n - 1] === Infinity ? -1 : dist[n - 1];
}

